{
  "arguments": [
    {
      "claim": "The officer exercised effective authority and control over the ABiH units that carried out the murders, satisfying the control element of superior responsibility.",
      "reasoning": "His appointment as Chief of the Main Staff, rotating Deputy Commander and leader of an Inspection Team gave him the power to issue orders, coordinate combat activities and supervise the forces operating in the Grabovica area; under the Rome Statute a \"superior shall be criminally responsible… where… the crimes concerned activities that were within the effective responsibility and control of the superior\" and customary law holds commanders criminally responsible for war crimes committed pursuant to their orders.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "With respect to superior and subordinate relationships not described in paragraph (a), a superior shall be criminally responsible for crimes within the jurisdiction of the Court committed by subordinates under his or her effective authority and control, as a result of his or her failure to exercise control properly over such subordinates, where: (ii) The crimes concerned activities that were within the effective responsibility and control of the superior;"
        },
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 152,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed pursuant to their orders."
        }
      ]
    },
    {
      "claim": "The officer knew, or should have known, that the murders were being committed by ABiH troops.",
      "reasoning": "He learned of the killings on the evening of 9 September, and given his coordinating role and the billeting of troops with civilians, the information was readily available to him; both the Rome Statute and customary IHL impose liability when a superior either knows or, owing to the circumstances, should have known of the crimes.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "With respect to superior and subordinate relationships not described in paragraph (a), a superior shall be criminally responsible… where: (i) The superior either knew, or consciously disregarded information which clearly indicated, that the subordinates were committing or about to commit such crimes;"
        },
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 153,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed by their subordinates if they knew, or had reason to know, that the subordinates were about to commit or were committing such crimes and did not take all necessary and reasonable measures in their power to prevent their commission, or if such crimes had been committed, to punish the persons responsible."
        }
      ]
    },
    {
      "claim": "The officer failed to take all necessary and reasonable measures to prevent or punish the murders, thereby breaching his duty of command responsibility.",
      "reasoning": "His only response was to instruct a team member to cooperate with an investigation already underway; he did not order the immediate arrest of the perpetrators, did not issue orders to halt further attacks, nor did he ensure disciplinary action, which the standards of the Rome Statute and customary law require as \"all necessary and reasonable measures\" within his power.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "With respect to superior and subordinate relationships not described in paragraph (a), a superior shall be criminally responsible… where: (iii) The superior failed to take all necessary and reasonable measures within his or her power to prevent or repress their commission or to submit the matter to the competent authorities for investigation and prosecution."
        },
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 153,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed by their subordinates… and did not take all necessary and reasonable measures in their power to prevent their commission, or if such crimes had been committed, to punish the persons responsible."
        },
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "86(2)",
          "quoted_text": "The fact that a breach of the Conventions or of this Protocol was committed by a subordinate does not absolve his superiors from penal or disciplinary responsibility, as the case may be, if they knew, or had information which should have enabled them to conclude in the circumstances at the time, that he was committing or was going to commit such a breach and if they did not take all feasible measures within their power to prevent or repress the breach."
        }
      ]
    },
    {
      "claim": "The officer’s limited formal hierarchical position does not excuse liability because effective control is determined by factual authority, not merely rank.",
      "reasoning": "International jurisprudence treats functional control—such as the ability to issue orders, coordinate operations and supervise troops—as sufficient for superior responsibility; the officer’s duties to consult on drastic proposals and to coordinate combat activities demonstrate such factual control, satisfying the \"effective authority and control\" requirement of the Rome Statute and the customary rule that commanders are liable for crimes committed by subordinates under their command.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "With respect to superior and subordinate relationships not described in paragraph (a), a superior shall be criminally responsible for crimes… under his or her effective authority and control…"
        },
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 152,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed pursuant to their orders."
        }
      ]
    }
  ]
}

